import { Component, Host, Prop, h } from "@stencil/core";

/**
 * @since 1.1.41
 * @status beta
 *
 */
@Component({
	tag: "hbr-chat-message",
	styleUrl: "chat-message.scss",
	shadow: true,
})
export class HbrChatMessage {
	@Prop({ reflect: true }) variant: "user" | "assistant" = "user";

	render() {
		return (
			<Host>
				<div
					class={{
						"chat-message": true,
						[`chat-message__${this.variant}`]: true,
					}}
					part="base"
				>
					<slot />
					{this.variant === "assistant" ? (
						<div class="chat-message__gradient-border" />
					) : null}
				</div>
			</Host>
		);
	}
}
